ALTER TABLE "expenses" ADD CONSTRAINT "expenses_rate_consistency_check" CHECK (("expenses"."currency_code" = "expenses"."base_currency_code" and "expenses"."rate_num" is null and "expenses"."rate_den" is null and "expenses"."base_amount_minor" = "expenses"."amount_minor") or ("expenses"."currency_code" <> "expenses"."base_currency_code" and "expenses"."rate_num" is not null and "expenses"."rate_den" is not null and "expenses"."rate_num" > 0 and "expenses"."rate_den" > 0 and "expenses"."rate_num" <= 1000000000000000 and "expenses"."rate_den" <= 1000000000000000));--> statement-breakpoint
ALTER TABLE "payments" ADD CONSTRAINT "payments_base_amount_minor_check" CHECK ("payments"."base_amount_minor" > 0 and "payments"."base_amount_minor" <= 1000000000000000);--> statement-breakpoint
